:root { color-scheme: dark; font-family: system-ui, sans-serif; }
* { box-sizing: border-box; }
body { display: flex; min-height: 100vh; margin: 0; flex-direction: column; color: #e2e8f0; background: #0f172a; }
.toolbar { display: flex; align-items: center; justify-content: space-between; gap: 18px; padding: 14px 22px; border-bottom: 1px solid #334155; background: #1e293b; }
.toolbar h1 { margin: 0; font-size: 1rem; }
.toolbar p { margin: 0; color: #94a3b8; font-size: .85rem; }
main { display: grid; flex: 1; grid-template-columns: 1fr 1fr; gap: 1px; background: #334155; }
main > section { display: flex; min-width: 0; flex-direction: column; background: #0f172a; }
main h2, main label { padding: 0 20px; }
main h2 { margin: 14px 0 4px; font-size: 1rem; }
main label { color: #94a3b8; font-size: .82rem; }
textarea, #preview { flex: 1; min-height: 360px; padding: 20px; overflow: auto; border: 0; color: #e2e8f0; background: #172033; font: 14px/1.7 ui-monospace, monospace; }
textarea { resize: none; }
textarea:focus-visible, #preview a:focus-visible { outline: 3px solid #fbbf24; outline-offset: -3px; }
#preview { background: #0f172a; font-family: system-ui, sans-serif; }
#preview h1, #preview h2, #preview h3 { padding: 0; color: #ffffff; }
#preview code { padding: 2px 5px; border-radius: 4px; color: #fde68a; background: #334155; }
#preview a { color: #93c5fd; }
@media (max-width: 760px) { main { grid-template-columns: 1fr; } textarea, #preview { min-height: 300px; } }

const input = document.querySelector('#markdown-input');
const preview = document.querySelector('#preview');
const stats = document.querySelector('#stats');

function appendInline(parent, text) {
  const tokenPattern = /(\*\*[^*]+\*\*|\x60[^\x60]+\x60|\[[^\]]+\]\([^)]+\))/g;
  let cursor = 0;
  for (const match of text.matchAll(tokenPattern)) {
    parent.append(document.createTextNode(text.slice(cursor, match.index)));
    const token = match[0];
    if (token.startsWith('**')) {
      const strong = document.createElement('strong');
      strong.textContent = token.slice(2, -2);
      parent.append(strong);
    } else if (token.startsWith(String.fromCharCode(96))) {
      const code = document.createElement('code');
      code.textContent = token.slice(1, -1);
      parent.append(code);
    } else {
      const parts = token.match(/^\[([^\]]+)\]\(([^)]+)\)$/);
      try {
        const url = new URL(parts[2], window.location.href);
        if (!['http:', 'https:'].includes(url.protocol)) throw new Error('不支持的链接协议');
        const link = document.createElement('a');
        link.textContent = parts[1];
        link.href = url.href;
        link.target = '_blank';
        link.rel = 'noopener noreferrer';
        parent.append(link);
      } catch {
        parent.append(document.createTextNode(parts[1]));
      }
    }
    cursor = match.index + token.length;
  }
  parent.append(document.createTextNode(text.slice(cursor)));
}

function renderMarkdown(value) {
  const fragment = new DocumentFragment();
  let list = null;
  value.split('\n').forEach(line => {
    if (line.startsWith('- ')) {
      if (!list) { list = document.createElement('ul'); fragment.append(list); }
      const item = document.createElement('li');
      appendInline(item, line.slice(2));
      list.append(item);
      return;
    }
    list = null;
    const heading = line.match(/^(#{1,3})\s+(.+)$/);
    const element = document.createElement(heading ? 'h' + heading[1].length : 'p');
    appendInline(element, heading ? heading[2] : line);
    fragment.append(element);
  });
  preview.replaceChildren(fragment);
}

function update() {
  renderMarkdown(input.value);
  stats.textContent = '字数：' + input.value.length + ' · 行数：' + input.value.split('\n').length;
}
input.addEventListener('input', update);
update();
